<?php declare(strict_types=1);require_once __DIR__.'/includes/auth.php';if(current_merchant()){redirect_to('/dashboard.php');} $error='';if($_SERVER['REQUEST_METHOD']==='POST'){verify_csrf();rate_limit('login',12,300);$email=filter_var($_POST['email']??'',FILTER_VALIDATE_EMAIL);$pass=(string)($_POST['password']??'');try{$q=db()->prepare('SELECT id,name,email,password FROM merchants WHERE email=?');$q->execute([$email?:'']);$m=$q->fetch();if($m&&password_verify($pass,$m['password'])){session_regenerate_id(true);$_SESSION['merchant_id']=(int)$m['id'];$_SESSION['merchant_name']=$m['name'];$_SESSION['merchant_email']=$m['email'];redirect_to('/dashboard.php');}}catch(Throwable $e){$error='Sign-in is unavailable. Check the database setup.';}if(!$error)$error='Email or password did not match.';}
?><!doctype html><html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Sign in — TG Gateways</title><link rel="stylesheet" href="/assets/css/style.css"></head><body class="auth-wrap"><main class="auth-card"><a class="brand" href="/"><img src="/assets/img/logo.svg" alt="">TG Gateways</a><h1>Welcome back</h1><p>Sign in to manage your orders, integrations and webhooks.</p><?php if($error):?><div class="note" style="border-color:#ffd5d5;background:#fff7f7;color:#9f3434"><?=h($error)?></div><?php endif?><form method="post"><input type="hidden" name="csrf" value="<?=h(csrf_token())?>"><div class="field"><label>Email address</label><input type="email" name="email" required autocomplete="username"></div><div class="field"><label>Password</label><input type="password" name="password" required autocomplete="current-password"></div><button class="btn" type="submit">Sign in securely →</button></form><p style="margin-top:22px">New deployment? Ask your administrator to provision a merchant account. <a style="color:var(--blue)" href="/docs.php">Setup docs</a></p></main></body></html>
